// HasDeployTarget applies the HasEdge predicate on the "deploy_target" edge.
func HasDeployTarget() predicate.DeployLog {
	return predicate.DeployLog(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, DeployTargetTable, DeployTargetColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasDeployTargetWith applies the HasEdge predicate on the "deploy_target" edge with a given conditions (other predicates).
func HasDeployTargetWith(preds ...predicate.DeployTarget) predicate.DeployLog {
	return predicate.DeployLog(func(s *sql.Selector) {
		step := newDeployTargetStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.DeployLog) predicate.DeployLog {
	return predicate.DeployLog(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.DeployLog) predicate.DeployLog {
	return predicate.DeployLog(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.DeployLog) predicate.DeployLog {
	return predicate.DeployLog(sql.NotPredicates(p))
}
